<script>
"use strict";

// ====================================================================
// Filesystem (static fake data — a browsable replica of a Linux system)
// ====================================================================
const filesystem = {
  type: "folder",
  children: {
    bin: {
      type: "folder",
      children: {
        bash:  { type: "file", content: "#!/bin/bash\necho hello" },
        cat:   { type: "file", content: "# cat utility — concatenate files" },
        ls:    { type: "file", content: "# list directory contents" },
        cp:    { type: "file", content: "# copy files and directories" },
        rm:    { type: "file", content: "# remove files" }
      }
    },
    etc: {
      type: "folder",
      children: {
        hostname: { type: "file", content: "ubuntu-desktop" },
        hosts:    { type: "file", content: "127.0.0.1 localhost\n::1 localhost" },
        passwd:   { type: "file", content: "root:x:0:0:root:/root:/bin/bash\nuser:x:1000:1000:Ubuntu User:/home/user:/bin/bash" },
        fstab:    { type: "file", content: "/dev/sda1 / ext4 defaults 0 1" },
        issue:    { type: "file", content: "Ubuntu 22.04 LTS" }
      }
    },
    home: {
      type: "folder",
      children: {
        user: {
          type: "folder",
          children: {
            Documents: {
              type: "folder",
              children: {
                "todo.md":     { type: "file", content: "# TODO\n- Buy groceries\n- Walk the dog\n- Finish project" },
                "report.txt":  { type: "file", content: "Quarterly report — looking good!" },
                "resume.pdf":  { type: "file", content: "[PDF DOCUMENT]" }
              }
            },
            Downloads: {
              type: "folder",
              children: {
                "wallpaper.jpg":  { type: "file", content: "[BINARY IMAGE DATA]" },
                "document.pdf":     { type: "file", content: "[PDF DOCUMENT]" },
                "archive.tar.gz":  { type: "file", content: "[GZIP ARCHIVE]" }
              }
            },
            Pictures: {
              type: "folder",
              children: {
                "sunset.png":    { type: "file", content: "[PNG IMAGE]" },
                "profile.jpg":   { type: "file", content: "[JPEG IMAGE]" },
                "family-photo.jpg": { type: "file", content: "[JPEG IMAGE]" }
              }
            },
            "notes.txt":    { type: "file", content: "Welcome to your home directory!" },
            ".config":      { type: "folder", children: {
              "settings.json": { type: "file", content: '{"theme":"dark","language":"en"}' }
            }}
          }
        }
      }
    },
    usr: {
      type: "folder",
      children: {
        bin: {
          type: "folder",
          children: {
            python3: { type: "file", content: "#!/usr/bin/python3" },
            node:    { type: "file", content: "# Node.js runtime" }
          }
        },
        share: {
          type: "folder",
          children: {
            applications: {
              type: "folder",
              children: {
                "firefox.desktop": { type: "file", content: "[Desktop Entry]\nName=Firefox\nExec=firefox" }
              }
            }
          }
        },
        local: {
          type: "folder",
          children: {
            bin: { type: "file", content: "#!/bin/bash\necho custom tool" }
          }
        }
      }
    },
    var: {
      type: "folder",
      children: {
        log: {
          type: "folder",
          children: {
            "syslog":     { type: "file", content: "Jan 01 00:00:01 ubuntu kernel: booting" },
            "auth.log":   { type: "file", content: "Jan 01 00:00:00 ubuntu sshd[1]: accepted" }
          }
        },
        tmp: {
          type: "folder",
          children: {
            "tempfile.tmp": { type: "file", content: "temporary data" }
          }
        },
        lib:   { type: "folder", children: {} },
        cache: { type: "folder", children: {} }
      }
    }
  }
};

// ====================================================================
// Files App — navigation logic
// ====================================================================
let currentPath = []; // array of path segments; [] means root "/"

function getFolderByPath(segments) {
  let node = filesystem;
  for (const seg of segments) {
    if (!node.children || !node.children[seg]) return null;
    node = node.children[seg];
  }
  return node;
}

function pathToString(segments) {
  return segments.length === 0 ? "/" : "/" + segments.join("/");
}

function renderFiles() {
  const folder = getFolderByPath(currentPath);
  const pathEl  = document.getElementById("files-path");
  const listEl  = document.getElementById("files-list");

  pathEl.textContent = pathToString(currentPath);
  listEl.innerHTML = "";

  if (!folder) {
    listEl.innerHTML = '<div style="color:#a0a0a0;padding:12px;">Folder not found</div>';
    return;
  }

  // Sort: folders first, then files, alphabetically
  const entries = Object.keys(folder.children).sort((a, b) => {
    const aFolder = folder.children[a].type === "folder";
    const bFolder = folder.children[b].type === "folder";
    if (aFolder && !bFolder) return -1;
    if (!aFolder && bFolder) return 1;
    return a.localeCompare(b);
  });

  entries.forEach(name => {
    const entry = folder.children[name];
    const item  = document.createElement("div");
    item.className = "fs-item " + entry.type;
    item.textContent = name;
    item.title = entry.type === "folder" ? "Double-click to open folder" : "File (double-click to view)";

    if (entry.type === "folder") {
      item.addEventListener("dblclick", () => {
        currentPath.push(name);
        renderFiles();
      });
    } else {
      item.style.cursor = "default";
      item.addEventListener("dblclick", () => {
        alert("📄 " + name + "\n\n" + (entry.content || ""));
      });
    }
    listEl.appendChild(item);
  });

  if (entries.length === 0) {
    listEl.innerHTML = '<div style="color:#666;padding:12px;text-align:center;font-style:italic;">This folder is empty</div>';
  }
}

document.getElementById("files-up").addEventListener("click", () => {
  if (currentPath.length > 0) {
    currentPath.pop();
    renderFiles();
  }
});

// ====================================================================
// Notepad App — tabbed, persistent via localStorage
// ====================================================================
let tabs = [];
let activeTabId = null;
let tabCounter = 0;

function loadTabs() {
  try {
    const saved       = localStorage.getItem("notepad-tabs");
    const savedActive = localStorage.getItem("notepad-active");
    const savedCounter = localStorage.getItem("notepad-counter");
    tabs = saved ? JSON.parse(saved) : [];
    tabCounter = savedCounter ? parseInt(savedCounter, 10) : 0;
    activeTabId = (savedActive && tabs.some(t => t.id === savedActive)) ? savedActive : null;
  } catch (e) {
    tabs = [];
    activeTabId = null;
    tabCounter = 0;
  }

  if (tabs.length === 0) {
    createNewTab();
  } else if (!activeTabId) {
    activeTabId = tabs[0].id;
  }

  saveTabs();
  renderTabs();
  renderEditor();
}

function saveTabs() {
  localStorage.setItem("notepad-tabs",    JSON.stringify(tabs));
  localStorage.setItem("notepad-active",  activeTabId);
  localStorage.setItem("notepad-counter", String(tabCounter));
}

function generateTabId() {
  tabCounter++;
  return "tab-" + tabCounter + "-" + Date.now();
}

function createNewTab() {
  const id = generateTabId();
  const tab = {
    id: id,
    name: "Tab " + (tabs.length + 1),
    content: ""
  };
  tabs.push(tab);
  activeTabId = id;
  saveTabs();
  renderTabs();
  renderEditor();
  const editor = document.getElementById("editor");
  editor.focus();
  editor.setSelectionRange(tab.content.length, tab.content.length);
}

function closeTab(id, e) {
  e.stopPropagation();
  const idx = tabs.findIndex(t => t.id === id);
  if (idx === -1) return;
  tabs.splice(idx, 1);
  if (tabs.length === 0) {
    createNewTab();
  } else if (activeTabId === id) {
    activeTabId = tabs[Math.min(idx, tabs.length - 1)].id;
  }
  saveTabs();
  renderTabs();
  renderEditor();
}

function switchToTab(id) {
  activeTabId = id;
  saveTabs();
  renderTabs();
  renderEditor();
  document.getElementById("editor").focus();
}

function renameTab(id) {
  const tab = tabs.find(t => t.id === id);
  if (!tab) return;
  const newName = prompt("Enter tab name:", tab.name);
  if (newName !== null && newName.trim() !== "") {
    tab.name = newName.trim();
    saveTabs();
    renderTabs();
    activeTabId = id;
    renderEditor();
  }
}

function renderTabs() {
  const tabsEl = document.getElementById("tabs");
  tabsEl.innerHTML = "";
  tabs.forEach(tab => {
    const tabEl = document.createElement("div");
    tabEl.className = "tab" + (tab.id === activeTabId ? " active" : "");
    tabEl.dataset.id = tab.id;
    tabEl.textContent = tab.name;
    tabEl.title = "Switch to " + tab.name;

    // Single-click: switch tab
    tabEl.addEventListener("click", (e) => {
      if (e.target.classList.contains("tab-close")) return;
      switchToTab(tab.id);
    });

    // Double-click: rename tab
    tabEl.addEventListener("dblclick", (e) => {
      if (e.target.classList.contains("tab-close")) return;
      renameTab(tab.id);
    });

    // Close button on each tab
    const closeBtn = document.createElement("span");
    closeBtn.className = "tab-close";
    closeBtn.textContent = "✕";
    closeBtn.title = "Close tab";
    closeBtn.addEventListener("click", (e) => closeTab(tab.id, e));
    tabEl.appendChild(closeBtn);

    tabsEl.appendChild(tabEl);
  });
}

function renderEditor() {
  const editor = document.getElementById("editor");
  const active = tabs.find(t => t.id === activeTabId);
  editor.value = active ? active.content : "";
}

function onEditorInput() {
  const editor = document.getElementById("editor");
  const active = tabs.find(t => t.id === activeTabId);
  if (active) {
    active.content = editor.value;
    saveTabs();
  }
}

document.getElementById("new-tab").addEventListener("click", createNewTab);
document.getElementById("editor").addEventListener("input", onEditorInput);

// ====================================================================
// Window Management — show/hide + draggable
// ====================================================================
let windowZ = 300;

function showWindow(win) {
  win.classList.add("active");
  win.style.zIndex = String(++windowZ);
}

function hideWindow(win) {
  win.classList.remove("active");
}

function initWindow(win) {
  const titlebar = win.querySelector(".win-titlebar");
  const closeBtn = win.querySelector(".win-close");

  closeBtn.addEventListener("click", () => {
    hideWindow(win);
  });

  let isDragging = false;
  let dragStartX = 0, dragStartY = 0;
  let startLeft = 0, startTop = 0;

  titlebar.addEventListener("mousedown", (e) => {
    if (e.button !== 0) return;
    // Bring to front
    win.style.zIndex = String(++windowZ);
    // Start drag
    isDragging = true;
    dragStartX = e.clientX;
    dragStartY = e.clientY;
    const rect = win.getBoundingClientRect();
    startLeft = rect.left;
    startTop = rect.top;
    win.style.left = startLeft + "px";
    win.style.top = startTop + "px";
    win.style.right = "auto";
    win.style.bottom = "auto";
    win.style.transform = "none";
    win.style.position = "fixed";
    titlebar.style.cursor = "grabbing";
    e.preventDefault();
  });

  document.addEventListener("mousemove", (e) => {
    if (!isDragging) return;
    const dx = e.clientX - dragStartX;
    const dy = e.clientY - dragStartY;
    win.style.left = (startLeft + dx) + "px";
    win.style.top = (startTop + dy) + "px";
  });

  document.addEventListener("mouseup", () => {
    isDragging = false;
    titlebar.style.cursor = "grab";
  });
}

// Initialize both windows
initWindow(document.getElementById("files-window"));
initWindow(document.getElementById("notepad-window"));

// Launcher buttons
document.getElementById("open-files").addEventListener("click", () => {
  showWindow(document.getElementById("files-window"));
});

document.getElementById("open-notepad").addEventListener("click", () => {
  showWindow(document.getElementById("notepad-window"));
  if (tabs.length === 0) createNewTab();
});

// ====================================================================
// Clock
// ====================================================================
function updateClock() {
  const now = new Date();
  const h = now.getHours().toString().padStart(2, "0");
  const m = now.getMinutes().toString().padStart(2, "0");
  document.getElementById("clock").textContent = h + ":" + m;
}

// ====================================================================
// Initialization
// ====================================================================
function init() {
  renderFiles();
  loadTabs();
  updateClock();
  setInterval(updateClock, 60000);
}

init();
</script>
</body>
</html>
